import { test, expect } from '@playwright/test';

test.describe('500 Server Error Page', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should display error page when server returns 500 error', async ({ page }) => {
    // Intercept the API call and respond with 500
    await page.route('**/api/data', (route) => {
      route.abort('failed');
      route.continue();
    });

    // Click the button that triggers the API call
    const loadButton = page.getByRole('button', { name: /load data/i });
    await loadButton.click();

    // Wait for the error state to be rendered
    await page.waitForTimeout(500);

    // Verify the error page is visible
    const errorContainer = page.getByText(/server error/i);
    await expect(errorContainer).toBeVisible();

    // Verify the error message contains the correct text
    const errorMessage = page.getByText(/500 internal server error/i);
    await expect(errorMessage).toBeVisible();

    // Verify the error page has a retry button
    const retryButton = page.getByRole('button', { name: /retry/i });
    await expect(retryButton).toBeVisible();

    // Verify the main content is not visible
    const dashboardContent = page.getByText(/dashboard overview/i);
    await expect(dashboardContent).not.toBeVisible();
  });

  test('should navigate back to dashboard on retry after 500 error', async ({ page }) => {
    // Intercept the API call and respond with 501
    await page.route('**/api/data', (route) => {
      route.abort('failed');
      route.continue();
    });

    // Click the button that triggers the API call
    const loadButton = page.getByRole('button', { name: /load data/i });
    await loadButton.click();

    // Wait for the error state to be rendered
    await page.waitForTimeout(500);

    // Verify the error page is visible
    const errorContainer = page.getByText(/server error/i);
    await expect(errorContainer).toBeVisible();

    // Click the retry button
    const retryButton = page.getByRole('button', { name: /retry/i });
    await retryButton.click();

    // Wait for the retry request
    await page.waitForTimeout(500);

    // Verify the error page is no longer visible
    await expect(errorContainer).not.toBeVisible();

    // Verify the dashboard content is visible
    const dashboardContent = page.getByText(/dashboard overview/i);
    await expect(dashboardContent).toBeVisible();

    // Verify the data is loaded successfully
    const dataTable = page.getByRole('region', { name: /data table/i });
    await expect(dataTable).toBeVisible();
  });
});
